package com.bank.fields.field;

import java.util.*;
import java.util.stream.Collectors;

// 'text' type: value is analyzed into lowercase tokens for word search.
public class TextField {
    // docId -> set of tokens indexed from that document's value
    private final Map<String, Set<String>> tokensByDoc = new HashMap<>();

    public void index(String docId, String value) {
        Set<String> tokens = Arrays.stream(value.toLowerCase().split("\\W+"))
                .filter(t -> !t.isBlank())
                .collect(Collectors.toSet());
        tokensByDoc.put(docId, tokens);
    }

    // match query: does the document contain this word?
    public Set<String> match(String word) {
        String w = word.toLowerCase();
        return tokensByDoc.entrySet().stream()
                .filter(e -> e.getValue().contains(w))
                .map(Map.Entry::getKey)
                .collect(Collectors.toCollection(TreeSet::new));
    }
}
