package com.bank.fields.field;

import java.util.*;
import java.util.stream.Collectors;

// 'keyword' type: whole value stored verbatim for exact match + aggregation.
public class KeywordField {
    private final Map<String, String> valueByDoc = new HashMap<>();

    public void index(String docId, String value) {
        valueByDoc.put(docId, value); // stored exactly, not tokenized
    }

    // term query: exact equality on the whole value.
    public Set<String> term(String exact) {
        return valueByDoc.entrySet().stream()
                .filter(e -> e.getValue().equals(exact))
                .map(Map.Entry::getKey)
                .collect(Collectors.toCollection(TreeSet::new));
    }

    // terms aggregation: count documents grouped by exact value.
    public Map<String, Long> aggregate() {
        return valueByDoc.values().stream()
                .collect(Collectors.groupingBy(v -> v, Collectors.counting()));
    }
}
