package com.bank.fields.mapping;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Reproduces dynamic mapping of a NEW string field: text + .keyword sub-field.
public class DynamicMapper {
    private static final Logger log = Logger.getLogger(DynamicMapper.class.getName());
    private final Map<String, String> mapping = new LinkedHashMap<>();

    public void onNewStringField(String field) {
        mapping.put(field, "text");                     // main field: analyzed
        mapping.put(field + ".keyword", "keyword(ignore_above=256)"); // sub-field
        log.info(() -> "dynamically mapped '" + field + "' -> text, '"
                + field + ".keyword' -> keyword");
    }

    public Map<String, String> getMapping() { return mapping; }
}
