package com.bank.fields.mapping;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Production choice: declare exactly the type each field needs.
public class ExplicitMapping {
    private static final Logger log = Logger.getLogger(ExplicitMapping.class.getName());
    private final Map<String, String> mapping = new LinkedHashMap<>();
    private boolean strict = true; // reject unmapped fields

    public ExplicitMapping define(String field, String type) {
        mapping.put(field, type);
        return this;
    }

    public void indexDocumentField(String field) {
        if (strict && !mapping.containsKey(field)) {
            throw new IllegalArgumentException(
                "strict mapping: unmapped field '" + field + "' rejected");
        }
        log.info(() -> "field '" + field + "' mapped as " + mapping.get(field));
    }

    public Map<String, String> getMapping() { return mapping; }
}
