package com.bank.fields;

import com.bank.fields.field.KeywordField;
import com.bank.fields.field.TextField;
import com.bank.fields.mapping.DynamicMapper;
import com.bank.fields.mapping.ExplicitMapping;
import com.bank.fields.model.Transaction;
import java.util.List;
import java.util.logging.Logger;

public class FieldDemo {
    private static final Logger log = Logger.getLogger(FieldDemo.class.getName());

    public static void main(String[] args) {
        List<Transaction> txns = List.of(
            new Transaction("TXN-1", "International Wire transfer", "SETTLED", "SAV2001"),
            new Transaction("TXN-2", "Domestic NEFT transfer", "SETTLED", "SAV2001"),
            new Transaction("TXN-3", "international wire incoming", "FAILED", "CUR3001"));

        // Dynamic mapping of a new string field 'description'.
        new DynamicMapper().onNewStringField("description");

        // text field on description → word search works.
        TextField description = new TextField();
        txns.forEach(t -> description.index(t.getId(), t.getDescription()));
        log.info(() -> "search description for 'wire' -> " + description.match("wire"));

        // keyword field on status → exact match + aggregation works.
        KeywordField status = new KeywordField();
        txns.forEach(t -> status.index(t.getId(), t.getStatus()));
        log.info(() -> "term status='FAILED' -> " + status.term("FAILED"));
        log.info(() -> "aggregate by status -> " + status.aggregate());

        // Explicit, strict production mapping.
        ExplicitMapping explicit = new ExplicitMapping()
            .define("description", "text")
            .define("status", "keyword")
            .define("account_id", "keyword")
            .define("created_at", "date");
        log.info(() -> "production mapping -> " + explicit.getMapping());
        try {
            explicit.indexDocumentField("unexpected_field"); // rejected by strict
        } catch (IllegalArgumentException e) {
            log.warning(e.getMessage());
        }
    }
}
